  "properties": {
    "subordinates": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "One or more direct reports (each a name or employee number) to submit this training need application for, e.g. ['John Silva'] or ['000010','000011']. Matches each entry first by exact employee number, then by a case-insensitive substring match against name, against the supervisor's live subordinate list. At least one is required. This is checked before anything else in this tool - the moment the supervisor names who the need is for, call this tool with ONLY subordinates (existingNeedName/newNeedName and the narrative fields all omitted) to validate them first; it's always safe since this call alone never submits anything. If any entry doesn't match exactly one subordinate, the tool returns NOT_SUBORDINATE or AMBIGUOUS (whichever applies) listing every problem entry plus eligibleSubordinates - fix all of them before ever asking about the need itself or narrative fields."
    },
    "existingNeedName": {
      "type": "string",
      "description": "The name (or partial name) of an already-existing training need category to attach this application to, e.g. 'Database & Data Management' - matches case-insensitively against the category list from getSupervisorTrainingNeeds' existingNeedCategories. Use this when the subordinate's need matches a category already on file (UAC 3.2) rather than describing something new. If more than one category matches, the tool returns status AMBIGUOUS with the candidates - ask which one and retry with the exact name. Either existingNeedName or newNeedName must be provided, not both. Only required once every named subordinate is already confirmed valid - do not collect or pass this on the subordinates-only validation call."
    },
    "newNeedName": {
      "type": "string",
      "description": "The requested need, in the supervisor's own words, when what's needed isn't already an existing category, e.g. 'Advanced Excel Macros' (UAC 3.3 - the 'Requested Need' field). Either existingNeedName or newNeedName must be provided, not both. Only required once every named subordinate is already confirmed valid - do not collect or pass this on the subordinates-only validation call."
    },
    "newNeedDescription": {
      "type": "string",
      "description": "A fuller description of the new requested need (the 'Requested Need Description' field on the real form). Optional even when newNeedName is given - only used alongside newNeedName, ignored for existingNeedName."
    },
    "objective": {
      "type": "string",
      "description": "The objective of this training need. Required - the training system itself rejects a submission without this (confirmed live: 'Please specify the objective.'). Unlike the self-application tool, there is no goal-linking option here (confirmed live: a real multi-subordinate submission sent IsGoalObject false with no ongoing-goals data at all) - always provide free text. Only enforced once every named subordinate is confirmed valid and the need is identified - do not ask the supervisor for this before that."
    },
    "relevanceToJob": {
      "type": "string",
      "description": "How this training need relates to the subordinate(s)' job. Required - the training system itself rejects a submission without this (confirmed live: 'Please specify the relevance to job.'). Only enforced once every named subordinate is confirmed valid and the need is identified - do not ask the supervisor for this before that."
    },
    "benefitToEmployee": {
      "type": "string",
      "description": "The benefit of this training need to the employee(s). Required - the training system itself rejects a submission without this (confirmed live: 'Please specify the benefit to you.'). Only enforced once every named subordinate is confirmed valid and the need is identified - do not ask the supervisor for this before that."
    },
    "benefitToCompany": {
      "type": "string",
      "description": "The benefit of this training need to the company. Required - the training system itself rejects a submission without this (confirmed live: 'Please specify the benefit to the company.'). Only enforced once every named subordinate is confirmed valid and the need is identified - do not ask the supervisor for this before that."
    }
  },
  "required": [
    "subordinates",
    "objective",
    "relevanceToJob",
    "benefitToEmployee",
    "benefitToCompany"
  ]
}

basic.transformer:
(async function (data, args, reqOptions) {
  try {
    const menus = (typeof BeaconBar !== "undefined" && BeaconBar.user && BeaconBar.user.metaData && BeaconBar.user.metaData.menus) || [];
    const hasAccess = Array.isArray(menus) && menus.some((menu) => typeof menu === "string" && menu.includes("TNDV9/TrainingNeed/Index?mvc=1&bs=4&App=000002"));
    if (!hasAccess) {
      return {
        status: "NO_ACCESS",
        message: "It seems you don't have access. Please check with the HR Admin"
      };
    }

    const subordinateQueries = Array.isArray(args.subordinates)
      ? args.subordinates.map((s) => String(s).trim()).filter((s) => s.length > 0)
      : [];
    const existingNeedName = args.existingNeedName ? String(args.existingNeedName).trim() : "";
    const newNeedName = args.newNeedName ? String(args.newNeedName).trim() : "";
    const newNeedDescription = args.newNeedDescription ? String(args.newNeedDescription).trim() : "";
    const objective = args.objective ? String(args.objective).trim() : "";
    const relevanceToJob = args.relevanceToJob ? String(args.relevanceToJob).trim() : "";
    const benefitToEmployee = args.benefitToEmployee ? String(args.benefitToEmployee).trim() : "";
    const benefitToCompany = args.benefitToCompany ? String(args.benefitToCompany).trim() : "";

    if (subordinateQueries.length === 0) {
      return {
        status: "VALIDATION_ERROR",
        message: "subordinates is required - provide at least one direct report's name or employee number."
      };
    }

    const headers = new Headers();
    headers.append("Accept", "*/*");
    headers.append("Content-Type", "application/json");
    headers.append("x-requested-with", "XMLHttpRequest");

    async function postJson(path, body) {
      const url = `${window.origin}/${reqOptions.sl}/${path}`;
      let response;
      try {
        response = await fetch(url, {
          method: "POST",
          headers: headers,
          body: body !== undefined ? JSON.stringify(body) : undefined
        });
      } catch (networkError) {
        throw new Error(`Could not reach ${path}: ${networkError.message}`);
      }
      const rawText = await response.text();
      let parsed = null;
      try {
        parsed = rawText ? JSON.parse(rawText) : null;
      } catch (parseError) {
        throw new Error(`${path} returned a non-JSON response (HTTP ${response.status}).`);
      }
      if (!response.ok) {
        const detail = (parsed && (parsed.Message || (parsed.Status && parsed.Status.Message))) || rawText.slice(0, 200);
        throw new Error(`${path} failed with HTTP ${response.status}: ${detail}`);
      }
      return parsed;
    }

    const detailsData = await postJson("TNDV9/TrainingNeed/GetTrainingNeedDetails", { requestType: "000002", WFMainID: "", PerfEmpNo: "" });
    if (!detailsData || !detailsData.Status || detailsData.Status.IsSuccessfull !== true) {
      return {
        status: "ERROR",
        message: (detailsData && detailsData.Status && detailsData.Status.Message) || "Failed to load the training need application form"
      };
    }
    const mainNeed = Array.isArray(detailsData.MainNeed) ? detailsData.MainNeed : [];
    const suborList = Array.isArray(detailsData.SuborList) ? detailsData.SuborList : [];
    if (suborList.length === 0) {
      return {
        status: "ERROR",
        message: "Could not load your subordinate list from the training need application form."
      };
    }

    const notFound = [];
    const ambiguous = [];
    const resolvedRecords = [];
    subordinateQueries.forEach((query) => {
      const lowerQuery = query.toLowerCase();
      let matches = suborList.filter((s) => (s.displayempno || "").toLowerCase() === lowerQuery);
      if (matches.length === 0) {
        matches = suborList.filter((s) => (s.empname || "").toLowerCase().includes(lowerQuery));
      }
      if (matches.length === 0) {
        notFound.push(query);
      } else if (matches.length > 1) {
        ambiguous.push({
          query: query,
          candidates: matches.map((s) => ({ employeeNumber: s.displayempno, name: s.empname, designation: s.designame }))
        });
      } else {
        resolvedRecords.push(matches[0]);
      }
    });

    const eligibleSubordinates = suborList.map((s) => ({ displayempno: s.displayempno, empname: s.empname, designation: s.designame }));

    if (notFound.length > 0) {
      return {
        status: "NOT_SUBORDINATE",
        message: `${notFound.map((q) => `"${q}"`).join(", ")} ${notFound.length === 1 ? "does" : "do"} not appear to be a subordinate you can submit a training need for. Please check the name(s) or employee number(s) and try again.`,
        eligibleSubordinates: eligibleSubordinates
      };
    }
    if (ambiguous.length > 0) {
      return {
        status: "AMBIGUOUS",
        message: `More than one subordinate matches ${ambiguous.map((a) => `"${a.query}"`).join(", ")}. Please specify using their exact employee number.`,
        candidates: ambiguous
      };
    }

    if (!existingNeedName && !newNeedName) {
      return {
        status: "VALIDATION_ERROR",
        message: "Provide either existingNeedName (to attach this application to an existing training need - see getSupervisorTrainingNeeds) or newNeedName (to submit a brand new one), not neither."
      };
    }
    if (existingNeedName && newNeedName) {
      return {
        status: "VALIDATION_ERROR",
        message: "Provide either existingNeedName or newNeedName, not both - the real form's Training Need Type is either 'Existing Need' or 'New Need', never both at once."
      };
    }

    let typecode;
    let needcode;
    let needname;
    let needdescription;
    if (existingNeedName) {
      const lowerNeedName = existingNeedName.toLowerCase();
      const needMatches = mainNeed.filter((n) => (n.needname || "").toLowerCase().includes(lowerNeedName));
      if (needMatches.length === 0) {
        return {
          status: "ERROR",
          message: `No existing training need matching "${args.existingNeedName}" was found. Use getSupervisorTrainingNeeds to see what's currently on file, or pass newNeedName to submit a new one.`
        };
      }
      if (needMatches.length > 1) {
        return {
          status: "AMBIGUOUS",
          message: `More than one existing training need matches "${args.existingNeedName}".`,
          ambiguousField: "existingNeedName",
          candidates: needMatches.map((n) => ({ needCode: n.needcode, needName: n.needname }))
        };
      }
      typecode = 1;
      needcode = needMatches[0].needcode;
      needname = "";
      needdescription = "";
    } else {
      typecode = 0;
      needcode = "000000";
      needname = newNeedName;
      needdescription = newNeedDescription;
    }

    const resolvedDisplayEmpNos = new Set(resolvedRecords.map((r) => r.displayempno));
    const empList = suborList.map((s) => ({
      tna_id: s.tna_id,
      raw_id: s.raw_id,
      empno: s.empno,
      displayempno: s.displayempno,
      empname: s.empname,
      designame: s.designame,
      app_approved: s.app_approved,
      typecode: s.typecode,
      selected: resolvedDisplayEmpNos.has(s.displayempno) ? 1 : 0,
      enrollstatus: s.enrollstatus,
      appid: s.appid,
      schmode: s.schmode,
      course: s.course,
      SchList: Array.isArray(s.SchList) ? s.SchList : [],
      EvalList: Array.isArray(s.EvalList) ? s.EvalList : []
    }));

    const payload = {
      tna_id: -1,
      needtype: "",
      typecode: typecode,
      needname: needname,
      needdescription: needdescription,
      status: "Pending",
      appdate: null,
      Strappdate: null,
      objective: objective,
      projectcode: "",
      supcomment: "",
      app_person: "",
      app_approved: 0,
      wfmainid: "",
      wfsequence: 0,
      rejectcomment: "",
      centrecode: "",
      reltojob: relevanceToJob,
      potentialyou: benefitToEmployee,
      potentialcomp: benefitToCompany,
      needcode: needcode,
      reqtypecode: "000002",
      reqtypename: "",
      editable: 1,
      enrollstatus: "",
      appid: 0,
      newneed: 1,
      disableneeds: 0,
      Attach: "0",
      FileNameAttached: "",
      EmpList: empList,
      AttchList: [],
      IsGoalObject: false,
      ExistingGoals: [],
      SelectedGoalCode: ""
    };

    const validation = await postJson("TNDV9/TrainingNeed/ValidateNeedApplication", payload);
    if (!validation || validation.IsSuccessfull !== true) {
      return {
        status: "VALIDATION_ERROR",
        message: (validation && validation.Message) || "The training need application was rejected during validation."
      };
    }

    const saveResult = await postJson("TNDV9/TrainingNeed/SaveNeedApplication", payload);
    if (!saveResult || saveResult.IsSuccessfull !== true) {
      return {
        status: "ERROR",
        message: (saveResult && saveResult.Message) || "Failed to submit the training need application."
      };
    }

    const results = Array.isArray(saveResult.Results) ? saveResult.Results : [];

    return {
      status: "SUCCESS",
      message: saveResult.Message || "Training need application submitted.",
      needSelectionType: existingNeedName ? "Existing" : "New",
      needCode: needcode,
      needName: existingNeedName ? mainNeed.find((n) => n.needcode === needcode).needname : newNeedName,
      submissions: results.map((r) => ({ employeeNumber: r.empno, success: r.success, status: r.status }))
    };

  } catch (error) {
    const errorMessage = error && error.message ? error.message : String(error);
    return {
      status: "ERROR",
      message: `Failed to submit the training need application: ${errorMessage}`,
      error: errorMessage
    };
  }
})

